insert into public.services (slug, title, copy, image, icon, points, sort_order, published) values
  ('corporate-events', 'Corporate Events', 'Organized at star banquets to brief employees on future strategies, facilitate discussions, and encourage the exchange of ideas and opinions.', '/media/s1.jpg', 'Building2', array['Annual conferences, townhalls and dealer meets', 'Award nights, gala dinners and celebrations', 'Stage design, production and AV management', 'Guest management, hospitality and logistics']::text[], 1, true),
  ('festival-activation', 'Festival Activation', 'Our team works closely with you to bring your vision to life, ensuring every detail reflects your unique style, personality and preferences.', '/media/s2.jpg', 'Sparkles', array['Durga Puja and festive property activations', 'Pandal branding and experience zones', 'Cultural performances and crowd engagement', 'Permissions, vendor and crowd-flow management']::text[], 2, true),
  ('exhibition', 'Exhibition', 'From venue selection and creative booth design to pre-event marketing, staff training and on-ground execution — every detail handled.', '/media/s3.jpg', 'LayoutPanelTop', array['Creative booth design and fabrication', 'Venue selection and space negotiation', 'Pre-event marketing and visitor drives', 'Trained staffing and lead capture']::text[], 3, true),
  ('brand-activation', 'Brand Activation', 'From immersive experiences to strategic engagements, we help brands inspire audiences and turn interactions into lasting loyalty.', '/media/s4.jpg', 'Megaphone', array['Mall, retail and campus experiences', 'Sampling, demo and photo-op installations', 'Promoter recruitment and training', 'Reporting, imagery and campaign analytics']::text[], 4, true),
  ('roadshows', 'Roadshows & Activations', 'We bring brands to life through engaging activations, immersive experiences and seamless on-ground execution.', '/media/s5.jpg', 'Truck', array['Multi-city route planning and permissions', 'Mobile stages, LED trucks and canters', 'Anchors, artists and crowd engagement', 'Daily reporting across every city']::text[], 5, true),
  ('sports-csr', 'Sports / CSR Events', 'Venue selection, catering, games, return gifts and more — activities designed to enhance community spirit, teamwork and health.', '/media/s6.jpg', 'Trophy', array['Corporate sports days and tournaments', 'Marathons, walkathons and health drives', 'CSR and community outreach programmes', 'Catering, trophies and return gifts']::text[], 6, true),
  ('trade-activation', 'Trade Activation', 'Channel and retail programmes that move product — designed for distributors, dealers and the last mile of your market.', '/media/s7.jpg', 'Store', array['Dealer, distributor and channel partner meets', 'In-shop branding and retail visibility drives', 'Trade schemes, incentives and loyalty programmes', 'Market-wise execution and on-ground reporting']::text[], 7, true),
  ('special-assignment', 'Special Assignment', 'One-of-a-kind mandates that don''t fit a template — conceptualised, produced and delivered end to end by a dedicated team.', '/media/s8.jpg', 'Star', array['Bespoke concepts and custom production', 'Government, institutional and CSR mandates', 'Milestone celebrations and inaugurations', 'Dedicated project team from brief to closure']::text[], 8, true)
