insert into public.gallery_categories (slug, title, copy, sort_order, published) values
  ('corporate-events', 'Corporate Events', 'Conferences, annual days and townhalls at star banquets — staged, produced and run end to end.', 1, true),
  ('festival-activation', 'Festival Activation', 'Durga Puja and festive properties built around culture, craft and crowd flow.', 2, true),
  ('exhibition', 'Exhibition', 'Booth design, fabrication, staffing and on-ground execution for trade fairs and expos.', 3, true),
  ('brand-activation', 'Brand Activation', 'Mall, retail and campus experiences that turn footfall into conversation.', 4, true),
  ('roadshows', 'Roadshows & Activations', 'Multi-city mobile stages, anchors and crowd engagement, city after city.', 5, true),
  ('sports-csr', 'Sports & CSR Events', 'Sports days, marathons and community initiatives built for teamwork and impact.', 6, true)
