insert into public.testimonials (quote, name, org, sort_order, published) values
  ('They took a two-line brief and returned a full experience. Our annual conference in Kolkata has never run this smoothly.', 'Regional Marketing Head', 'FMCG Major', 1, true),
  ('Three cities, nine days of roadshows, zero surprises. The on-ground team is calm, sharp and completely dependable.', 'Brand Manager', 'Telecom Brand', 2, true),
  ('The exhibition booth pulled the highest footfall we''ve had. Design, build and staffing were all handled end to end.', 'AVP Communications', 'Private Bank', 3, true);
insert into public.site_settings (key, value) values
  ('phone', '"9831085630"'::jsonb),
  ('email', '"niladdri@communicationevent.in"'::jsonb),
  ('address', '"Communication & Events, 335, Jodhpur Park, Kolkata 700068"'::jsonb),
  ('hero_video', '"/media/hero-loop.mp4"'::jsonb),
  ('hero_poster', '"/media/hero.jpg"'::jsonb),
  ('founder_image', '"/media/founder.jpg"'::jsonb),
  ('founder_name', '"Niladdri Biswas"'::jsonb),
  ('about_body', '["With over 3 decades of unparalleled proficiency in executing successful promotions, campaigns and events, our founder has a deep understanding of effectively engaging target audiences and creating memorable experiences that leave a lasting impact.","Whether it''s a large-scale product launch or an intimate brand activation, our founder''s expertise in logistics, marketing and event management ensures seamless execution and remarkable results. With a proven track record in executing mega events and working with international and national celebrities, he has successfully curated and promoted a diverse range of events, elevating the profiles of both established and up-and-coming artists.","Our team of professionals is driven by commitment, motivation and passion to produce memorable brand events. We have all the expertise under one roof to ensure the success of any activity."]'::jsonb),
  ('stats', '[{"value":100,"suffix":"+","label":"Brands Served"},{"value":1000,"suffix":"+","label":"Successful Events"},{"value":30,"suffix":"+","label":"Years of Excellence"}]'::jsonb)
